import { useEffect, useRef } from 'react';
import { DialogHeader } from '@kerfjs/ui/dialog-header';
import { EmptyState } from '@kerfjs/ui/empty-state';
import '@kerfjs/ui/layout.css';
import './item-dialog.css';

type Item = { id: string; title: string; summary: string; owner: string; updated: string };
export function ItemDialog({ open, items, selectedId, select, close, confirm }: {
  open: boolean; items: Item[]; selectedId: string | null;
  select: (id: string) => void; close: () => void; confirm: (id: string) => void;
}) {
  const dialog = useRef<HTMLDialogElement>(null);
  const selected = items.find(item => item.id === selectedId);
  useEffect(() => {
    const node = dialog.current!;
    if (!open) { if (node.open) node.close(); return; }
    const previous = document.activeElement as HTMLElement | null;
    if (!node.open) node.showModal();
    return () => { if (node.open) node.close(); if (previous?.isConnected) previous.focus(); };
  }, [open]);
  return <dialog ref={dialog} className="kui-layout item-dialog"
    aria-labelledby="item-dialog-title" aria-describedby="item-dialog-summary"
    onCancel={event => { event.preventDefault(); close(); }}>
    <DialogHeader title={<span id="item-dialog-title">Choose a project</span>}
      description={<span id="item-dialog-summary">Select a project to review its details, then open it.</span>} />
    <div className="kui-dialog-body dialog-scroll">
      <div className="master-detail">
        <fieldset className="item-list">
          <legend>Projects</legend>
          {items.map(item => <label key={item.id} className="item-option">
            <input type="radio" name="project" value={item.id} checked={selectedId === item.id}
              onChange={() => select(item.id)} />
            {item.title}
          </label>)}
          {items.length === 0 && <EmptyState title="No projects available" />}
        </fieldset>
        <section className="kui-section" aria-label="Selected project details" aria-live="polite">
          {selected ? <>
            <h2>{selected.title}</h2>
            <p>{selected.summary}</p>
            <dl className="kui-metadata">
              <dt>Owner</dt><dd>{selected.owner}</dd>
              <dt>Last updated</dt><dd>{selected.updated}</dd>
            </dl>
          </> : <p>Select a project to see its details.</p>}
        </section>
      </div>
    </div>
    <footer className="dialog-actions">
      <button type="button" onClick={close}>Cancel</button>
      <button type="button" disabled={!selected} onClick={() => selected && confirm(selected.id)}>Open project</button>
    </footer>
  </dialog>;
}

