.item-dialog { inline-size:min(56rem,calc(100vw - 2rem)); max-block-size:calc(100dvh - 2rem); padding:0; overflow:hidden; }
.item-dialog[open] { display:flex; flex-direction:column; }
.dialog-scroll { overflow:auto; min-block-size:0; }
.master-detail { display:grid; grid-template-columns:minmax(10rem,1fr) minmax(0,2fr); }
.item-list { min-inline-size:0; border:0; margin:0; }
.item-option { display:flex; align-items:center; min-block-size:2.75rem; overflow-wrap:anywhere; }
.dialog-actions { display:flex; flex-wrap:wrap; justify-content:flex-end; }
.kui-metadata dd { overflow-wrap:anywhere; }
:focus-visible { outline:2px solid currentColor; outline-offset:2px; }
@media(max-width:40rem) { .master-detail { grid-template-columns:minmax(0,1fr); } }
